/// _COUNTY_FIPS: [(state, county name)] -> 5-digit FIPS, in table order.
public let countyFIPSTable: [(state: String, name: String, fips: String)] = {
    var out: [(String, String, String)] = []
    for line in countyData.split(separator: "\n") {
        let head = line.prefix(6)              // "md 24 "
        let parts = head.split(separator: " ")
        guard parts.count == 2 else { continue }
        let st = String(parts[0]), sf = String(parts[1])
        for entry in line.dropFirst(6).split(separator: ";") {
            guard let eq = entry.lastIndex(of: "=") else { continue }
            out.append((st, String(entry[..<eq]), sf + entry[entry.index(after: eq)...]))
        }
    }
    return out
}()
